CREATE OR REPLACE FUNCTION eflow_work_edit.guard_details()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb; b jsonb; relevant text[]; locked text[]; policy jsonb; key text;
 is_task boolean:=tg_table_name='tasks'; reason text; due_changed boolean; root_id uuid;
begin
 if tg_op='DELETE' then
  if eflow_work_edit.node_started(old.task_id,old.id) then
   raise exception 'Started work and its history cannot be deleted.' using errcode='22023';end if;
  return old;
 end if;
 a:=to_jsonb(old);b:=to_jsonb(new);root_id:=case when is_task then old.id else (a->>'task_id')::uuid end;
 if a ? 'dependency_ids' then a:=jsonb_set(a,'{dependency_ids}',eflow_work_edit.dependency_value(a->'dependency_ids'));end if;
 if b ? 'dependency_ids' then b:=jsonb_set(b,'{dependency_ids}',eflow_work_edit.dependency_value(b->'dependency_ids'));end if;
 if is_task and a->>'deleted_at' is null and b->>'deleted_at' is not null
  and eflow_work_edit.task_started(root_id) then
  raise exception 'Started work and its history cannot be deleted.' using errcode='22023';end if;
 relevant:=case when is_task then array['title','description','priority','deadline','due_date','start_date','dependency_ids',
  'acceptance_criteria','definition_of_done','estimated_hours','budget_impact','group_id','workspace_position','linked_project_id','org_id']
  else array['title','priority','due_date','start_date','dependency_ids','is_standalone','parent_subtask_id','sibling_order','task_id'] end;
 if not exists(select 1 from unnest(relevant) f where a->f is distinct from b->f) then return new;end if;
 -- Preserve private project-deletion detachment, with its existing exact predicate.
 if is_task and eflow_phase6.project_deletion_detach(a,b) then return new;end if;
 -- Legacy non-project work retains its existing contracts and guards.
 if eflow_r7.root(root_id) is null then return new;end if;
 if b->>'status' in ('for_review','completed','cancelled') then
  raise exception 'Work details are read-only during review or after completion.' using errcode='22023';end if;
 policy:=eflow_work_edit.state(root_id,case when is_task then null else old.id end);
 if not coalesce((policy->>'details')::boolean,false) then
  raise exception 'Work details are read-only. Refresh the work or use its existing review or reopen action.' using errcode='42501';end if;
 locked:=case when is_task then array['description','start_date','dependency_ids','estimated_hours','budget_impact',
  'acceptance_criteria','definition_of_done','group_id','workspace_position','linked_project_id','org_id']
  else array['start_date','dependency_ids','is_standalone','parent_subtask_id','sibling_order','task_id'] end;
 if not (policy->>'planning')::boolean and exists(select 1 from unnest(locked) f where a->f is distinct from b->f) then
  raise exception 'Start date, prerequisites and structure cannot change after work has started.' using errcode='22023';end if;
 due_changed:=a->'due_date' is distinct from b->'due_date' or (is_task and a->'deadline' is distinct from b->'deadline');
 if due_changed and not (policy->>'due')::boolean then
  raise exception 'Only the supervising Lead or authorized Office Head can reschedule this work.' using errcode='42501';end if;
 reason:=case when is_task then current_setting('eflow.work_detail_change_reason',true) else b->>'due_date_change_reason' end;
 if due_changed and (policy->>'started')::boolean and nullif(btrim(reason),'') is null then
  raise exception 'Enter a reason for changing the due date.' using errcode='22023';end if;
 if due_changed and length(coalesce(reason,''))>1000 then
  raise exception 'Keep the schedule change reason within 1,000 characters.' using errcode='22023';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION eflow_r9.record_project_field_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous jsonb:=to_jsonb(old); current_row jsonb:=to_jsonb(new);
  project uuid; task uuid; fields text[]; event_title text; changes text;
  actor_name text:=coalesce((select full_name from public.profiles where id=auth.uid()),'System');
begin
  if tg_table_name='project_office_members' then
    if coalesce(new.can_edit,false)=coalesce(old.can_edit,false) then return new; end if;
    select project_id into project from public.project_offices where id=new.project_office_id;
    select full_name into changes from public.profiles where id=new.user_id;
    event_title:=case when new.can_edit then 'Project editing access granted' else 'Project editing access removed' end;
  else
    if tg_table_name='projects' then
      project:=new.id;
      fields:=array['title','description','scope','priority','start_date','target_date','status','project_lead_id'];
      event_title:='Project details changed · '||new.title;
    else
      project:=new.linked_project_id;
      task:=new.id;
      fields:=array['title','description','priority','start_date','deadline','estimated_hours','group_id','deleted_at','archived_at'];
      event_title:='Task details changed · '||new.title;
    end if;
    select string_agg(initcap(replace(field,'_',' '))||': '||
      coalesce(nullif(previous->>field,''),'None')||' → '||coalesce(nullif(current_row->>field,''),'None'),E'\n')
      into changes from unnest(fields) field where previous->field is distinct from current_row->field;
  end if;
  if project is not null and changes is not null then
    insert into public.project_field_history(project_id,task_id,title,detail,actor_name)
      values(project,task,event_title,changes,actor_name);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.create_task_with_details(p_payload jsonb)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller uuid := auth.uid();
  caller_profile public.profiles;
  target_org uuid;
  selected_assignee uuid := nullif(p_payload ->> 'assigned_to', '')::uuid;
  target_project uuid := nullif(p_payload ->> 'linked_project_id', '')::uuid;
  initial_status text;
  task_priority text := coalesce(nullif(trim(p_payload ->> 'priority'), ''), 'medium');
  created_task public.tasks;
  v_enroll_ids uuid[];
begin
  if caller is null then
    raise exception 'Authentication is required to create a task'
      using errcode = '42501';
  end if;

  select * into caller_profile
  from public.profiles
  where id = caller and is_active;
  if not found then
    raise exception 'An active eFlow profile is required to create a task'
      using errcode = '42501';
  end if;

  if nullif(trim(p_payload ->> 'title'), '') is null then
    raise exception 'Task title is required'
      using errcode = '22023';
  end if;
  if task_priority not in ('low', 'medium', 'high') then
    raise exception 'Invalid task priority'
      using errcode = '22023';
  end if;

  target_org := coalesce(
    nullif(p_payload ->> 'org_id', '')::uuid,
    caller_profile.org_id
  );
  if not public.can_create_scoped_work(target_org, caller) then
    raise exception 'You cannot create tasks in this organization'
      using errcode = '42501';
  end if;

  if selected_assignee is not null and not exists (
    select 1 from public.profiles
    where id = selected_assignee and is_active
  ) then
    raise exception 'Task assignee must be an active eFlow user'
      using errcode = '22023';
  end if;

  if target_project is not null and nullif(p_payload ->> 'source_collaboration_draft_id', '') is null then
    select array_remove(
      array[selected_assignee] || array(
        select value::uuid
        from jsonb_array_elements_text(coalesce(p_payload -> 'team_member_ids', '[]'::jsonb))
      ),
      null
    ) into v_enroll_ids;
    perform eflow_r7.ensure_office_members(target_project, target_org, v_enroll_ids);
  end if;

  initial_status := case
    when selected_assignee is null then 'pending_assignment'
    else 'todo'
  end;

  insert into public.tasks (
    title, description, status, priority, assigned_to, assignee_name,
    department, org_id, team_id, team_name, team_member_ids, team_member_names,
    deadline, due_date, tags, recommended_employee_ids, recommendation_reasoning,
    recommendation_source, recommendation_lead_id, reviewer_id, backup_reviewer_id,
    acceptance_criteria, definition_of_done, dependency_ids, burnout_warning,
    proposal_id, proposal_title, program_id, program_title, project_id, project_title,
    activity_id, activity_title, activity_schedule, hierarchy_path, import_batch_id,
    barangay, estimated_hours, budget_impact, linked_project_id, milestone_id,
    percent_complete, created_by
  ) values (
    trim(p_payload ->> 'title'),
    nullif(p_payload ->> 'description', ''),
    initial_status,
    task_priority,
    selected_assignee,
    coalesce(p_payload ->> 'assignee_name', ''),
    coalesce(p_payload ->> 'department', ''),
    target_org,
    coalesce(p_payload ->> 'team_id', ''),
    coalesce(p_payload ->> 'team_name', ''),
    array(select value::uuid from jsonb_array_elements_text(coalesce(p_payload -> 'team_member_ids', '[]'::jsonb))),
    array(select value from jsonb_array_elements_text(coalesce(p_payload -> 'team_member_names', '[]'::jsonb))),
    coalesce(p_payload ->> 'deadline', ''),
    coalesce(p_payload ->> 'due_date', p_payload ->> 'deadline', ''),
    array(select value from jsonb_array_elements_text(coalesce(p_payload -> 'tags', '[]'::jsonb))),
    array(select value::uuid from jsonb_array_elements_text(coalesce(p_payload -> 'recommended_employee_ids', '[]'::jsonb))),
    nullif(p_payload ->> 'recommendation_reasoning', ''),
    nullif(p_payload ->> 'recommendation_source', ''),
    nullif(p_payload ->> 'recommendation_lead_id', '')::uuid,
    nullif(p_payload ->> 'reviewer_id', '')::uuid,
    nullif(p_payload ->> 'backup_reviewer_id', '')::uuid,
    coalesce(p_payload -> 'acceptance_criteria', '[]'::jsonb),
    nullif(p_payload ->> 'definition_of_done', ''),
    coalesce(array(select value::uuid from jsonb_array_elements_text(coalesce(p_payload -> 'dependency_ids', '[]'::jsonb))), '{}'::uuid[]),
    coalesce((p_payload ->> 'burnout_warning')::boolean, false),
    nullif(p_payload ->> 'proposal_id', ''),
    nullif(p_payload ->> 'proposal_title', ''),
    nullif(p_payload ->> 'program_id', ''),
    nullif(p_payload ->> 'program_title', ''),
    nullif(p_payload ->> 'project_id', ''),
    nullif(p_payload ->> 'project_title', ''),
    nullif(p_payload ->> 'activity_id', ''),
    nullif(p_payload ->> 'activity_title', ''),
    nullif(p_payload ->> 'activity_schedule', ''),
    nullif(p_payload ->> 'hierarchy_path', ''),
    nullif(p_payload ->> 'import_batch_id', ''),
    nullif(p_payload ->> 'barangay', ''),
    coalesce((p_payload ->> 'estimated_hours')::numeric, 0),
    coalesce((p_payload ->> 'budget_impact')::numeric, 0),
    target_project,
    nullif(p_payload ->> 'milestone_id', '')::uuid,
    coalesce((p_payload ->> 'percent_complete')::int, 0),
    caller
  )
  returning * into created_task;

  return created_task;
end;
$function$

CREATE OR REPLACE FUNCTION public.phase3_patch_task(p_task_id uuid, p_patch jsonb)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.tasks; p public.projects; k text; deps uuid[]; cycle_found boolean; v_today date; v_start date; v_due text; v_due_day date;
begin
 if jsonb_typeof(p_patch)<>'object' then raise exception 'Invalid task changes' using errcode='22023'; end if;
 select * into t from public.tasks where id=p_task_id and deleted_at is null;
 if not found then raise exception 'Task not available' using errcode='42501'; end if;
 if eflow_publication.planning_lead(t.linked_project_id,t.org_id) then
   select * into p from public.projects where id=t.linked_project_id for update;
   else select * into p from eflow_phase6.lock_project(t.linked_project_id); end if;
 if p.id is null or not coalesce(eflow_publication.planning_lead(p.id,t.org_id) or (public.can_create_scoped_work(t.org_id,auth.uid()) and (public.can_manage_project(p.id,auth.uid()) or eflow_phase6.head(p.id,t.org_id,auth.uid())) and public.can_manage_task(t.id,auth.uid())),false) then
  raise exception 'Only the responsible Office Head can edit project structure' using errcode='42501'; end if;
 -- Serialize dependency edits and re-read after the project lock.
 select * into t from public.tasks where id=p_task_id for update;
 if p.status in ('completed','archived') or t.archived_at is not null or t.status in ('completed','cancelled') then raise exception 'Completed or archived work is read-only' using errcode='22023'; end if;
 for k in select jsonb_object_keys(p_patch) loop
  if k not in ('title','priority','deadline','start_date','estimated_hours','budget_impact','dependency_ids','group_id','workspace_position','change_reason') then raise exception 'Protected task field: %',k using errcode='22023'; end if;
 end loop;
 if p_patch ? 'title' and (length(btrim(coalesce(p_patch->>'title',''))) not between 1 and 300) then raise exception 'Enter a task title (up to 300 characters)' using errcode='22023'; end if;
 if p_patch ? 'priority' and coalesce(p_patch->>'priority','') not in ('low','medium','high') then raise exception 'Invalid priority' using errcode='22023'; end if;
 if p_patch ? 'estimated_hours' and (coalesce((p_patch->>'estimated_hours')::numeric,0)<0 or coalesce((p_patch->>'estimated_hours')::numeric,0)>100000) then raise exception 'Effort must be between 0 and 100000 hours' using errcode='22023'; end if;
 if p_patch ? 'budget_impact' and (coalesce((p_patch->>'budget_impact')::numeric,0)<0 or coalesce((p_patch->>'budget_impact')::numeric,0)>1000000000000) then raise exception 'Invalid budget estimate' using errcode='22023'; end if;
 if p_patch ? 'dependency_ids' then
  if jsonb_typeof(p_patch->'dependency_ids')<>'array' or jsonb_array_length(p_patch->'dependency_ids')>100 then raise exception 'Invalid dependency list' using errcode='22023'; end if;
  select coalesce(array_agg(distinct value::uuid),'{}'::uuid[]) into deps from jsonb_array_elements_text(p_patch->'dependency_ids');
  if exists(select 1 from unnest(deps) d where d=t.id or not exists(select 1 from public.tasks x where x.id=d and x.linked_project_id=p.id and x.deleted_at is null)) then raise exception 'Dependencies must be other available tasks in this project' using errcode='22023'; end if;
  with recursive edges(id,path) as (
   select d,array[d] from unnest(deps) d union all
   select d,e.path||d from edges e join public.tasks x on x.id=e.id cross join lateral unnest(x.dependency_ids) d where not d=any(e.path)
  ) select exists(select 1 from edges where id=t.id) into cycle_found;
  if cycle_found then raise exception 'Dependencies cannot form a cycle' using errcode='22023'; end if;
 end if;
 if p_patch ? 'deadline' or p_patch ? 'start_date' then
  v_today := (clock_timestamp() at time zone 'Asia/Manila')::date;
  v_start := case when p_patch ? 'start_date' then nullif(p_patch->>'start_date','')::date else t.start_date end;
  v_due := case when p_patch ? 'deadline' then nullif(p_patch->>'deadline','') else nullif(t.deadline,'') end;
  if p_patch ? 'deadline' and v_due is not null then
   if v_due !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception 'Enter a valid due date.' using errcode='22023';
   end if;
   v_due_day := v_due::date;
   if v_due_day < v_today then raise exception 'Choose today or a future due date.' using errcode='22023'; end if;
   p_patch:=jsonb_set(p_patch,'{deadline}',to_jsonb(v_due));
  end if;
  if v_start is not null and v_start is distinct from t.start_date and v_start < v_today then
   raise exception 'Choose today or a future start date.' using errcode='22023';
  end if;
  if v_start is not null and v_due is not null and v_start > left(v_due,10)::date then
   raise exception 'Due date cannot be before the start date.' using errcode='22023';
  end if;
 end if;
 perform set_config('eflow.work_detail_change_reason',coalesce(p_patch->>'change_reason',''),true);
 update public.tasks set
  title=case when p_patch ? 'title' then btrim(p_patch->>'title') else title end,
  priority=case when p_patch ? 'priority' then p_patch->>'priority' else priority end,
  deadline=case when p_patch ? 'deadline' then coalesce(p_patch->>'deadline','') else deadline end,
  due_date=case when p_patch ? 'deadline' then coalesce(p_patch->>'deadline','') else due_date end,
  start_date=case when p_patch ? 'start_date' then nullif(p_patch->>'start_date','')::date else start_date end,
  estimated_hours=case when p_patch ? 'estimated_hours' then coalesce((p_patch->>'estimated_hours')::double precision,0) else estimated_hours end,
  budget_impact=case when p_patch ? 'budget_impact' then coalesce((p_patch->>'budget_impact')::double precision,0) else budget_impact end,
  dependency_ids=case when p_patch ? 'dependency_ids' then deps else dependency_ids end,
  group_id=case when p_patch ? 'group_id' then (p_patch->>'group_id')::uuid else group_id end,
  workspace_position=case when p_patch ? 'workspace_position' then (p_patch->>'workspace_position')::integer else workspace_position end
 where id=t.id returning * into t;
 perform set_config('eflow.work_detail_change_reason','',true);
 if t.start_date is not null and nullif(t.deadline,'') is not null and t.start_date>left(t.deadline,10)::date then raise exception 'Start date must precede the due date' using errcode='22023'; end if;
 return t;
end; $function$

CREATE OR REPLACE FUNCTION public.commit_collaboration_draft(p_draft_id uuid, p_revision_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text := '';
  draft_row public.proposal_collaboration_drafts;
  revision_row public.proposal_collaboration_revisions;
  readiness jsonb;
  snapshot jsonb;
  task_item jsonb;
  project_item record;
  activity_item record;
  project_row public.projects;
  milestone_row public.milestones;
  task_row public.tasks;
  owner_org public.proposal_collaboration_orgs;
  governance_org public.proposal_collaboration_orgs;
  primary_reviewer uuid;
  backup_reviewer uuid;
  task_lead uuid;
  primary_org uuid;
  activity_primary_org uuid;
  member_ids uuid[];
  member_names text[];
  supporting_value text;
  selected_reviewer uuid;
  selected_backup uuid;
  route_mode text;
  project_ids uuid[] := '{}'::uuid[];
  project_target date;
  project_start date;
  milestone_due date;
  import_batch text;
begin
  if caller is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  if not public.can_manage_collaboration_draft(p_draft_id, caller) then
    raise exception 'Only the owning organization may commit this proposal' using errcode = '42501';
  end if;
  select * into draft_row from public.proposal_collaboration_drafts where id = p_draft_id for update;
  if not found then raise exception 'Collaboration draft not found' using errcode = 'P0002'; end if;
  if draft_row.status = 'committed' or draft_row.committed_at is not null then raise exception 'This proposal has already been committed' using errcode = '22023'; end if;
  if draft_row.current_revision_id is distinct from p_revision_id then raise exception 'Only the current revision can be committed' using errcode = '22023'; end if;
  select * into revision_row from public.proposal_collaboration_revisions where id = p_revision_id and draft_id = p_draft_id;
  if not found then raise exception 'Revision does not belong to this draft' using errcode = '22023'; end if;
  readiness := public.collaboration_readiness(p_draft_id);
  if not coalesce((readiness ->> 'ready')::boolean, false) then
    raise exception 'Approval requirements not complete: %', coalesce(readiness -> 'blockers', '[]'::jsonb)::text using errcode = '22023';
  end if;

  snapshot := revision_row.snapshot;
  if jsonb_typeof(snapshot -> 'tasks') <> 'array' or jsonb_array_length(snapshot -> 'tasks') = 0 then
    raise exception 'The approved revision contains no tasks' using errcode = '22023';
  end if;
  select * into owner_org from public.proposal_collaboration_orgs
  where draft_id = p_draft_id and participation_role = 'owner';
  if not found or owner_org.org_id <> draft_row.owner_org_id then raise exception 'Owner organization configuration is invalid' using errcode = '22023'; end if;

  select * into governance_org from public.proposal_collaboration_orgs
  where draft_id = p_draft_id and participation_role = 'governance'
  order by created_at limit 1;
  if found then
    select coalesce(
      (select membership.user_id from public.organization_memberships membership join public.profiles profile on profile.id = membership.user_id and profile.is_active where membership.organization_id = governance_org.org_id and membership.membership_role = 'primary_approver'),
      (select organization.head_user_id from public.organizations organization join public.profiles profile on profile.id = organization.head_user_id and profile.is_active where organization.id = governance_org.org_id)
    ) into primary_reviewer;
    select coalesce(
      (select membership.user_id from public.organization_memberships membership join public.profiles profile on profile.id = membership.user_id and profile.is_active where membership.organization_id = governance_org.org_id and membership.membership_role = 'backup_approver'),
      null::uuid
    ) into backup_reviewer;
    if primary_reviewer is null and backup_reviewer is null then raise exception 'Governance organization requires an active named primary or backup governance reviewer' using errcode = '22023'; end if;
  end if;

  import_batch := 'collaboration-' || p_draft_id::text || '-r' || revision_row.revision_number::text;

  -- Validate every staffing and responsibility record before the first insert.
  for task_item in
    select value from jsonb_array_elements(snapshot -> 'tasks')
    where coalesce((value ->> 'enabled')::boolean, true)
  loop
    task_lead := nullif(task_item ->> 'leadMemberId', '')::uuid;
    primary_org := coalesce(nullif(task_item ->> 'primaryOrgId', '')::uuid, draft_row.owner_org_id);
    member_ids := array(select value::uuid from jsonb_array_elements_text(coalesce(task_item -> 'assignedMemberIds', '[]'::jsonb)));
    if nullif(btrim(task_item ->> 'title'), '') is null then raise exception 'Every selected task needs a title' using errcode = '22023'; end if;
    if task_lead is null or not member_ids @> array[task_lead] then raise exception 'Every Task Leader must belong to their proposed team' using errcode = '22023'; end if;
    if not exists (select 1 from public.proposal_collaboration_orgs eligible where eligible.draft_id = p_draft_id and eligible.org_id = primary_org and eligible.staffing_enabled) then
      raise exception 'Task primary organization is not staffing-enabled for this proposal' using errcode = '22023';
    end if;
    if not exists (select 1 from public.profiles profile where profile.id = task_lead and profile.is_active) then raise exception 'Every Task Leader must be active' using errcode = '22023'; end if;
    if exists (
      select 1 from unnest(member_ids) member_id
      left join public.profiles profile on profile.id = member_id and profile.is_active
      where profile.id is null or not exists (
        select 1 from public.proposal_collaboration_orgs eligible
        where eligible.draft_id = p_draft_id and eligible.org_id = profile.org_id and eligible.staffing_enabled
      )
    ) then raise exception 'Every proposed employee must be active and belong to a staffing-enabled participating organization' using errcode = '22023'; end if;
    for supporting_value in select value from jsonb_array_elements_text(coalesce(task_item -> 'supportingOrgIds', '[]'::jsonb)) loop
      if supporting_value::uuid = primary_org or not exists (select 1 from public.proposal_collaboration_orgs where draft_id = p_draft_id and org_id = supporting_value::uuid) then
        raise exception 'Task supporting organization configuration is invalid' using errcode = '22023';
      end if;
    end loop;
    if governance_org.org_id is not null and task_lead = primary_reviewer and backup_reviewer is null then
      raise exception 'Approval requirements not complete: primary governance reviewer is Task Lead and no backup reviewer is configured' using errcode = '22023';
    end if;
    if governance_org.org_id is not null and task_lead = backup_reviewer and primary_reviewer is null then
      raise exception 'Approval requirements not complete: backup governance reviewer is Task Lead and no primary reviewer is configured' using errcode = '22023';
    end if;
  end loop;

  for project_item in
    select task ->> 'projectId' as project_key,
      max(task ->> 'projectTitle') as project_title,
      max(task ->> 'programId') as program_id,
      max(task ->> 'programTitle') as program_title,
      min(case when task ->> 'deadline' ~ '^\d{4}-\d{2}-\d{2}' then left(task ->> 'deadline', 10)::date end) as start_date,
      max(case when task ->> 'deadline' ~ '^\d{4}-\d{2}-\d{2}' then left(task ->> 'deadline', 10)::date end) as target_date
    from jsonb_array_elements(snapshot -> 'tasks') task
    where coalesce((task ->> 'enabled')::boolean, true)
    group by task ->> 'projectId'
  loop
    if nullif(btrim(project_item.project_key), '') is null or nullif(btrim(project_item.project_title), '') is null then raise exception 'Every task must belong to a valid project' using errcode = '22023'; end if;
    project_start := project_item.start_date;
    project_target := project_item.target_date;
    insert into public.projects (
      org_id, title, description, owner_id, status, priority, start_date, target_date,
      created_by, proposal_id, proposal_title, program_id, program_title,
      source_type, source_file_name, source_collaboration_draft_id, source_collaboration_revision_id
    ) values (
      draft_row.owner_org_id, project_item.project_title,
      case when draft_row.source_type = 'ai_pdf' then 'Imported through approved collaboration: ' else 'Approved collaborative plan: ' end || draft_row.title,
      draft_row.owner_user_id, 'active', 'medium', project_start, project_target,
      caller, coalesce(snapshot ->> 'proposalId', p_draft_id::text), draft_row.title,
      project_item.program_id, project_item.program_title, draft_row.source_type,
      draft_row.source_file_name, p_draft_id, p_revision_id
    ) returning * into project_row;
    project_ids := array_append(project_ids, project_row.id);
    insert into public.proposal_collaboration_commit_projects (draft_id, revision_id, project_key, project_id)
    values (p_draft_id, p_revision_id, project_item.project_key, project_row.id);

    insert into public.project_organizations (
      project_id, organization_id, participation_role, staffing_enabled, source_draft_id, source_revision_id
    ) select project_row.id, participating.org_id, participating.participation_role,
      participating.staffing_enabled, p_draft_id, p_revision_id
    from public.proposal_collaboration_orgs participating where participating.draft_id = p_draft_id;

    insert into public.project_members (project_id, user_id, role)
    values (project_row.id, draft_row.owner_user_id, 'owner')
    on conflict (project_id, user_id) do update set role = excluded.role;
    insert into public.project_members (project_id, user_id, role)
    select distinct project_row.id, member_id, 'member'
    from jsonb_array_elements(snapshot -> 'tasks') task
    cross join lateral jsonb_array_elements_text(coalesce(task -> 'assignedMemberIds', '[]'::jsonb)) member_text(value)
    cross join lateral (select member_text.value::uuid as member_id) member
    where task ->> 'projectId' = project_item.project_key
      and coalesce((task ->> 'enabled')::boolean, true)
    on conflict (project_id, user_id) do nothing;

    for activity_item in
      select task ->> 'activityId' as activity_key,
        max(task ->> 'activityTitle') as activity_title,
        max(task ->> 'activitySchedule') as activity_schedule,
        max(task ->> 'activityPrimaryOrgId') as primary_org_id,
        (jsonb_agg(coalesce(task -> 'activitySupportingOrgIds', '[]'::jsonb)) -> 0) as supporting_org_ids,
        max(case when task ->> 'deadline' ~ '^\d{4}-\d{2}-\d{2}' then left(task ->> 'deadline', 10)::date end) as due_date
      from jsonb_array_elements(snapshot -> 'tasks') task
      where task ->> 'projectId' = project_item.project_key and coalesce((task ->> 'enabled')::boolean, true)
      group by task ->> 'activityId'
    loop
      milestone_due := activity_item.due_date;
      insert into public.milestones (project_id, title, description, due_date, sort_order)
      values (project_row.id, activity_item.activity_title,
        case when nullif(activity_item.activity_schedule, '') is null then '' else 'Original schedule: ' || activity_item.activity_schedule end,
        milestone_due, (select count(*) from public.milestones where project_id = project_row.id))
      returning * into milestone_row;
      activity_primary_org := coalesce(nullif(activity_item.primary_org_id, '')::uuid, draft_row.owner_org_id);
      if not exists (
        select 1 from public.proposal_collaboration_orgs
        where draft_id = p_draft_id and org_id = activity_primary_org and staffing_enabled
      ) then raise exception 'Activity primary organization must be a staffing-enabled participant' using errcode = '22023'; end if;
      insert into public.milestone_organizations (milestone_id, organization_id, responsibility_role)
      values (milestone_row.id, activity_primary_org, 'primary');
      for supporting_value in select value from jsonb_array_elements_text(coalesce(activity_item.supporting_org_ids, '[]'::jsonb)) loop
        if supporting_value::uuid <> activity_primary_org then
          if not exists (
            select 1 from public.proposal_collaboration_orgs
            where draft_id = p_draft_id and org_id = supporting_value::uuid
          ) then raise exception 'Activity supporting organization is not participating' using errcode = '22023'; end if;
          insert into public.milestone_organizations (milestone_id, organization_id, responsibility_role)
          values (milestone_row.id, supporting_value::uuid, 'supporting') on conflict do nothing;
        end if;
      end loop;

      for task_item in
        select value from jsonb_array_elements(snapshot -> 'tasks')
        where value ->> 'projectId' = project_item.project_key
          and value ->> 'activityId' = activity_item.activity_key
          and coalesce((value ->> 'enabled')::boolean, true)
      loop
        task_lead := nullif(task_item ->> 'leadMemberId', '')::uuid;
        primary_org := coalesce(nullif(task_item ->> 'primaryOrgId', '')::uuid, activity_primary_org);
        member_ids := array(select value::uuid from jsonb_array_elements_text(coalesce(task_item -> 'assignedMemberIds', '[]'::jsonb)));
        select array_agg(profile.full_name order by member_position.ordinality)
        into member_names
        from unnest(member_ids) with ordinality member_position(member_id, ordinality)
        join public.profiles profile on profile.id = member_position.member_id;

        if governance_org.org_id is not null then
          route_mode := 'governance';
          selected_reviewer := case when task_lead = primary_reviewer then backup_reviewer else primary_reviewer end;
          selected_backup := case
            when task_lead = backup_reviewer or backup_reviewer = selected_reviewer then null
            else backup_reviewer
          end;
          if selected_reviewer is null or selected_reviewer = task_lead then raise exception 'No valid governance reviewer exists for task "%"', task_item ->> 'title' using errcode = '22023'; end if;
        else
          route_mode := 'organization_default';
          selected_reviewer := null;
          selected_backup := null;
        end if;

        insert into public.tasks (
          title, description, status, priority, assigned_to, assignee_name,
          department, org_id, team_id, team_name, team_member_ids, team_member_names,
          deadline, due_date, tags, recommended_employee_ids,
          recommendation_reasoning, recommendation_source, recommendation_lead_id,
          reviewer_id, backup_reviewer_id, proposal_id, proposal_title,
          program_id, program_title, project_id, project_title,
          activity_id, activity_title, activity_schedule, hierarchy_path,
          import_batch_id, linked_project_id, milestone_id, percent_complete, estimated_hours,
          review_route_mode, source_collaboration_draft_id,
          source_collaboration_revision_id, created_by
        ) values (
          btrim(task_item ->> 'title'), nullif(task_item ->> 'description', ''), 'todo',
          coalesce(nullif(task_item ->> 'priority', ''), 'medium'), task_lead,
          (select full_name from public.profiles where id = task_lead),
          primary_org::text, primary_org, primary_org::text,
          (select name from public.organizations where id = primary_org),
          member_ids, coalesce(member_names, '{}'::text[]),
          coalesce(task_item ->> 'deadline', ''), coalesce(task_item ->> 'deadline', ''),
          array(select value from jsonb_array_elements_text(coalesce(task_item -> 'requiredSkills', '[]'::jsonb))),
          member_ids, nullif(task_item ->> 'reasoning', ''),
          case when draft_row.source_type = 'ai_pdf' then 'import' else null end,
          task_lead, selected_reviewer, selected_backup,
          coalesce(snapshot ->> 'proposalId', p_draft_id::text), draft_row.title,
          project_item.program_id, project_item.program_title,
          project_item.project_key, project_item.project_title,
          activity_item.activity_key, activity_item.activity_title,
          activity_item.activity_schedule,
          concat_ws(' > ', draft_row.title, project_item.program_title, project_item.project_title, activity_item.activity_title),
          import_batch, project_row.id, milestone_row.id, 0,
          greatest(coalesce((task_item ->> 'estimatedHours')::numeric, 0), 0),
          route_mode, p_draft_id, p_revision_id, caller
        ) returning * into task_row;
        if task_item ? 'subtasks' then
          if jsonb_typeof(task_item->'subtasks') is distinct from 'array'
             or jsonb_array_length(task_item->'subtasks') > 30
             or exists (
               select 1 from jsonb_array_elements(task_item->'subtasks') as step(value)
               where jsonb_typeof(step.value) <> 'string'
                 or char_length(btrim(step.value #>> '{}')) not between 1 and 300
             ) then
            raise exception 'Enter up to 30 named subtasks for %', task_row.title using errcode = '22023';
          end if;
          insert into public.subtasks (task_id, title, source, position, sibling_order, created_by)
          select task_row.id, btrim(step.title), 'ai_extracted', (step.position - 1)::integer,
                 (step.position - 1)::integer, caller
          from jsonb_array_elements_text(task_item->'subtasks') with ordinality as step(title, position);
        end if;

        insert into public.task_organizations (task_id, organization_id, responsibility_role)
        values (task_row.id, primary_org, 'primary');
        for supporting_value in select value from jsonb_array_elements_text(coalesce(task_item -> 'supportingOrgIds', '[]'::jsonb)) loop
          if supporting_value::uuid <> primary_org then
            insert into public.task_organizations (task_id, organization_id, responsibility_role)
            values (task_row.id, supporting_value::uuid, 'supporting') on conflict do nothing;
          end if;
        end loop;
      end loop;
    end loop;
  end loop;

  update public.proposal_collaboration_drafts
  set status = 'committed', committed_at = now(), working_snapshot = revision_row.snapshot
  where id = p_draft_id;
  select coalesce(full_name, 'Owner') into caller_name from public.profiles where id = caller;
  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action, after_data, org_id
  ) values (
    caller, caller_name, 'collaboration_draft', p_draft_id::text,
    'collaboration.committed',
    jsonb_build_object('revisionId', p_revision_id, 'revision', revision_row.revision_number, 'projectIds', to_jsonb(project_ids)),
    draft_row.owner_org_id
  );
  insert into public.notifications (user_id, type, title, message, actor_id, actor_name, proposal_id, org_id, entity_type)
  select distinct approver_id, 'collaboration_approved', 'Work plan published',
    '"' || draft_row.title || '" is now operational in eFlow.', caller, caller_name,
    p_draft_id::text, participating.org_id, 'collaboration_draft'
  from public.proposal_collaboration_orgs participating
  cross join lateral public.organization_approver_ids(participating.org_id) approver_id
  where participating.draft_id = p_draft_id and approver_id <> caller;
  return jsonb_build_object(
    'draftId', p_draft_id,
    'revisionId', p_revision_id,
    'revisionNumber', revision_row.revision_number,
    'projectIds', to_jsonb(project_ids),
    'projectCount', cardinality(project_ids)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.phase5_import_project_work(p_project_id uuid, p_request_id uuid, p_review jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 p public.projects; receipt public.project_import_batches; g jsonb; t jsonb; s jsonb; o jsonb; k text;
 group_id uuid; task_row public.tasks; task_id uuid; mappings jsonb:='{}'; group_ids jsonb:='[]';
 task_count integer:=0; sub_count integer:=0; group_count integer:=0; n integer; sub_n integer;
 keys text[]:='{}'; office_keys text[]:='{}'; result jsonb; patch jsonb;
begin
 if exists(select 1 from jsonb_array_elements(coalesce(p_review->'groups','[]')) as source_group(value) cross join lateral jsonb_array_elements(coalesce(source_group.value->'tasks','[]')) as source_task(value) cross join lateral jsonb_array_elements(coalesce(source_task.value->'subitems','[]')) as source_item(value) where source_item.value ?| array['parentSubtaskId','parent_subtask_id','children','subitems']) then raise exception 'Nested imports need a hierarchy format; parent links cannot be flattened';end if;
 select * into p from public.projects where id=p_project_id for update;
 if not found or auth.uid() is null or not public.can_create_scoped_work(p.org_id,auth.uid()) or not public.can_manage_project(p.id,auth.uid()) then
  raise exception 'Only the responsible Office Head can import project work' using errcode='42501'; end if;
 -- The project lock serializes imports and checks retries before any inserts.
 select * into receipt from public.project_import_batches where id=p_request_id;
 if found then
  if receipt.project_id<>p.id or receipt.created_by<>auth.uid() or receipt.review<>p_review then
   raise exception 'This import reference was already used for another review' using errcode='22023'; end if;
  return receipt.result;
 end if;
 if p.status in ('completed','archived') then raise exception 'Closed project structure is read-only' using errcode='22023'; end if;
 if jsonb_typeof(p_review) is distinct from 'object' or p_review->>'schemaVersion' is distinct from '1'
 or jsonb_typeof(p_review->'groups') is distinct from 'array' or jsonb_array_length(p_review->'groups') not between 1 and 30
 or jsonb_typeof(p_review->'offices') is distinct from 'array' or jsonb_array_length(p_review->'offices')>100
 or octet_length(p_review::text)>2000000 then raise exception 'Invalid reviewed project import' using errcode='22023'; end if;
 for o in select value from jsonb_array_elements(p_review->'offices') loop
  if length(btrim(coalesce(o->>'name',''))) not between 1 and 200 or length(coalesce(o->>'evidence','')) not between 1 and 2000
   or o->>'confirmed' is distinct from 'true' or length(coalesce(o->>'key','')) not between 1 and 80 or o->>'key'=any(office_keys) then
   raise exception 'Confirm each source-named Office responsibility before importing' using errcode='22023'; end if;
  if nullif(o->>'officeId','') is not null and not exists(select 1 from public.organizations where id=(o->>'officeId')::uuid) then
   raise exception 'Choose an existing Office or keep the proposed name unmatched' using errcode='22023'; end if;
  office_keys:=array_append(office_keys,o->>'key');
 end loop;
 -- Preflight the complete hierarchy; malformed fields cannot become authority.
 for g in select value from jsonb_array_elements(p_review->'groups') loop
  if length(btrim(coalesce(g->>'title',''))) not between 1 and 120 or jsonb_typeof(g->'tasks') is distinct from 'array'
   or jsonb_array_length(g->'tasks') not between 1 and 100 then raise exception 'Each group needs a title and tasks' using errcode='22023'; end if;
  for t in select value from jsonb_array_elements(g->'tasks') loop
   for k in select jsonb_object_keys(t) loop
    if k not in ('key','title','description','priority','startDate','dueDate','estimatedHours','officeKey','dependencies','subitems','sourceQuote','advisory') then
     raise exception 'Unsupported import task field: %',k using errcode='22023'; end if;
   end loop;
   if length(coalesce(t->>'key','')) not between 1 and 80 or t->>'key'=any(keys)
    or length(btrim(coalesce(t->>'title',''))) not between 1 and 300 or length(coalesce(t->>'description',''))>10000
    or coalesce(t->>'priority','') not in ('low','medium','high') or jsonb_typeof(t->'dependencies') is distinct from 'array'
    or jsonb_array_length(t->'dependencies')>100 or jsonb_typeof(t->'subitems') is distinct from 'array' or jsonb_array_length(t->'subitems')>30
    or coalesce((t->>'estimatedHours')::numeric,-1) not between 0 and 100000
    or (nullif(t->>'officeKey','') is not null and not t->>'officeKey'=any(office_keys)) then
    raise exception 'Invalid reviewed task, effort, or Office responsibility' using errcode='22023'; end if;
   keys:=array_append(keys,t->>'key'); task_count:=task_count+1;
   for s in select value from jsonb_array_elements(t->'subitems') loop
    if length(btrim(coalesce(s->>'title',''))) not between 1 and 300 then raise exception 'Enter a subitem title' using errcode='22023'; end if;
   end loop;
  end loop;
 end loop;
 if task_count>100 then raise exception 'Import up to 100 tasks at once' using errcode='22023'; end if;
 if coalesce((p_review->>'applyProjectDetails')::boolean,false) then
  if length(btrim(coalesce(p_review->'project'->>'title',''))) not between 1 and 300 or length(coalesce(p_review->'project'->>'description',''))>10000 then
   raise exception 'Invalid reviewed project details' using errcode='22023'; end if;
  update public.projects set title=btrim(p_review->'project'->>'title'),
   description=coalesce(p_review->'project'->>'description','')||case when nullif(p_review->'project'->>'objectives','') is not null then E'\n\nObjectives\n'||(p_review->'project'->>'objectives') else '' end,
   start_date=nullif(p_review->'project'->>'startDate','')::date,target_date=nullif(p_review->'project'->>'targetDate','')::date
   where id=p.id returning * into p;
  if p.start_date>p.target_date then raise exception 'Project start must precede target date' using errcode='22023'; end if;
 end if;
 task_count:=0;
 for g in select value from jsonb_array_elements(p_review->'groups') loop
  group_id:=nullif(g->>'existingGroupId','')::uuid;
  if group_id is not null then
   if not exists(select 1 from public.project_groups where id=group_id and project_id=p.id) then raise exception 'Choose a group in this project' using errcode='22023'; end if;
  else
   select coalesce(max(position)+1,0) into n from public.project_groups where project_id=p.id;
   insert into public.project_groups(project_id,title,color,position) values(p.id,btrim(g->>'title'),coalesce(nullif(g->>'color',''),'#579bfc'),n) returning id into group_id;
   group_count:=group_count+1;
  end if;
  group_ids:=group_ids||to_jsonb(group_id::text);
  for t in select value from jsonb_array_elements(g->'tasks') loop
   task_row:=public.phase3_create_task(p.id,group_id,t->>'title'); task_id:=task_row.id;
   update public.tasks set description=coalesce(t->>'description',''),import_batch_id=p_request_id::text,
    recommendation_source='ai_workspace_reviewed',recommendation_reasoning='Human-reviewed project import; people and Office access remain unassigned.' where id=task_id;
   patch:=jsonb_build_object('priority',t->>'priority','start_date',nullif(t->>'startDate',''),'deadline',coalesce(t->>'dueDate',''),'estimated_hours',(t->>'estimatedHours')::numeric);
   perform public.phase3_patch_task(task_id,patch);
   mappings:=mappings||jsonb_build_object(t->>'key',task_id); task_count:=task_count+1; sub_n:=0;
   for s in select value from jsonb_array_elements(t->'subitems') loop
    insert into public.subtasks(task_id,title,source,position,created_by,due_date)
     values(task_id,btrim(s->>'title'),'ai_extracted',sub_n,auth.uid(),nullif(s->>'dueDate','')::date);
    sub_n:=sub_n+1;sub_count:=sub_count+1;
   end loop;
  end loop;
 end loop;
 -- Translate draft keys only after all canonical IDs exist. The Phase 3 guard
 -- verifies project scope and rejects self-dependencies/cycles transactionally.
 for g in select value from jsonb_array_elements(p_review->'groups') loop
  for t in select value from jsonb_array_elements(g->'tasks') loop
   if exists(select 1 from jsonb_array_elements_text(t->'dependencies') d where not mappings ? d.value) then
    raise exception 'A dependency points to an omitted task. Restore it or remove the dependency' using errcode='22023'; end if;
   perform public.phase3_patch_task((mappings->> (t->>'key'))::uuid,jsonb_build_object('dependency_ids',
    coalesce((select jsonb_agg(mappings->>d.value) from jsonb_array_elements_text(t->'dependencies') d),'[]'::jsonb)));
  end loop;
 end loop;
 result:=jsonb_build_object('taskCount',task_count,'subitemCount',sub_count,'groupCount',group_count,'taskIds',mappings,'groupIds',group_ids);
 insert into public.project_import_batches(id,project_id,created_by,review,result) values(p_request_id,p.id,auth.uid(),p_review,result);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.phase6_guard_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.projects; t public.tasks; candidate uuid; actor uuid:=auth.uid();
begin if tg_op='UPDATE' and eflow_phase6.project_deletion_detach(to_jsonb(old),to_jsonb(new)) then return new;end if;
 if tg_op='UPDATE' and eflow_r9.internal(coalesce((select linked_project_id from public.tasks where id=coalesce((to_jsonb(new)->>'task_id')::uuid,(to_jsonb(new)->>'id')::uuid)),(select project_id from public.personal_tasks where id=coalesce((to_jsonb(new)->>'task_id')::uuid,(to_jsonb(new)->>'id')::uuid)))) then return new;end if;
 if tg_op='UPDATE' and (to_jsonb(new)-array['team_member_ids','team_member_names','updated_at'])=(to_jsonb(old)-array['team_member_ids','team_member_names','updated_at']) and eflow_r7.internal(old.id) then return new;end if;
 if tg_op='UPDATE' and pg_trigger_depth()>1 and (to_jsonb(new)-array['subtask_count','subtask_completed_count','last_activity_at','updated_at'])=(to_jsonb(old)-array['subtask_count','subtask_completed_count','last_activity_at','updated_at']) then return new;end if;
 if tg_op in ('DELETE','UPDATE') then t:=old;else t:=new;end if;
 select * into p from public.projects where id=t.linked_project_id;
 if p.id is null or p.source_collaboration_draft_id is not null or not eflow_phase6.shared(p.id) then if tg_op='DELETE' then return old;else return new;end if;end if;
 -- Maintenance via service_role remains available; JWT users cannot bypass it
 -- through definer RPCs because auth.uid() remains their original identity.
 if actor is not null then
  if p.status in ('completed','archived') then raise exception 'Closed project work is read-only' using errcode='42501';end if;
  if tg_op='UPDATE' and (new.linked_project_id is distinct from old.linked_project_id or new.source_collaboration_draft_id is distinct from old.source_collaboration_draft_id) then raise exception 'Project identity is protected' using errcode='42501';end if;
  if tg_op='UPDATE' and new.org_id is distinct from old.org_id then
   if not public.phase2_is_office_head(actor,p.org_id) or old.status<>'pending_assignment' or old.assigned_to is not null or old.recommendation_lead_id is not null or cardinality(coalesce(old.team_member_ids,'{}'::uuid[]))>0 or exists(select 1 from public.subtasks where task_id=old.id and (status<>'todo' or assigned_to is not null or cardinality(coalesce(assigned_to_ids,'{}'::uuid[]))>0)) or new.assigned_to is not null or new.recommendation_lead_id is not null or cardinality(coalesce(new.team_member_ids,'{}'::uuid[]))>0 then raise exception 'Office handover requires unstarted, unassigned work' using errcode='42501';end if;
  elsif tg_op='INSERT' then
   if not eflow_phase6.head(p.id,t.org_id,actor) then raise exception 'Only the responsible Office Head can create work' using errcode='42501';end if;
  elsif not eflow_phase6.work(t.id,actor)
    and not (tg_op='UPDATE' and coalesce(eflow_r9.can_edit_selected_project(p.id,t.org_id,actor),false)
      and (to_jsonb(new)-array['title','priority','deadline','due_date','start_date','estimated_hours','updated_at'])
        =(to_jsonb(old)-array['title','priority','deadline','due_date','start_date','estimated_hours','updated_at']))
    and not (tg_op='UPDATE' and public.phase2_is_office_head(actor,p.org_id) and (to_jsonb(new)-array['group_id','workspace_position','updated_at'])=(to_jsonb(old)-array['group_id','workspace_position','updated_at'])) then raise exception 'Your project access is read-only for this Office work' using errcode='42501';end if;
  if tg_op='UPDATE' and (new.assigned_to is distinct from old.assigned_to or new.recommendation_lead_id is distinct from old.recommendation_lead_id or new.team_member_ids is distinct from old.team_member_ids or new.team_id is distinct from old.team_id) and not eflow_phase6.head(p.id,new.org_id,actor) then raise exception 'Only the responsible Office Head can choose its employees' using errcode='42501';end if;
 end if;
 if tg_op<>'DELETE' then
  if not exists(select 1 from public.project_offices where project_id=p.id and office_id=new.org_id and relationship_type in ('lead','collaborating') and invitation_status='joined') then raise exception 'Responsible Office must be a joined collaborator' using errcode='23514';end if;
  foreach candidate in array array_remove(array[new.assigned_to,new.recommendation_lead_id]||coalesce(new.team_member_ids,'{}'::uuid[]),null) loop
   if not exists(select 1 from public.profiles q where q.id=candidate and q.org_id=new.org_id and q.is_active and q.role<>'admin' and (public.phase2_is_office_head(candidate,new.org_id) or new.org_id=p.org_id or exists(select 1 from public.project_office_members m join public.project_offices o on o.id=m.project_office_id where o.project_id=p.id and o.office_id=new.org_id and m.user_id=candidate))) then raise exception 'Select active project members from the responsible Office' using errcode='42501';end if;
  end loop;
  return new;
 end if;return old;
end $function$

CREATE OR REPLACE FUNCTION eflow_r9.edit_selected_project_task(p_task_id uuid, p_patch jsonb)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.tasks; p public.projects; k text; deps uuid[]; cycle_found boolean; v_today date; v_start date; v_due text; v_due_day date;
begin
 if jsonb_typeof(p_patch)<>'object' then raise exception 'Invalid task changes' using errcode='22023'; end if;
 select * into t from public.tasks where id=p_task_id and deleted_at is null;
 if not found then raise exception 'Task not available' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('r9:'||t.linked_project_id::text,0));
     select * into p from public.projects where id=t.linked_project_id for update;
 if not found or t.proposed_office_identity_id is not null or not coalesce(eflow_r9.can_edit_selected_project(p.id,t.org_id,auth.uid()),false) then
  raise exception 'Editing access for this project task is required.' using errcode='42501'; end if;
 -- Serialize dependency edits and re-read after the project lock.
 select * into t from public.tasks x where x.id=p_task_id and x.linked_project_id=p.id
      and x.org_id=t.org_id and x.proposed_office_identity_id is null and x.deleted_at is null for update;
     if not found then raise exception 'Task access changed. Reopen the project.' using errcode='42501'; end if;
 if p.status in ('completed','archived') or t.archived_at is not null or t.status in ('for_review','completed','cancelled') then raise exception 'Completed or archived work is read-only' using errcode='22023'; end if;
 for k in select jsonb_object_keys(p_patch) loop
  if k not in ('title','priority','deadline','start_date','estimated_hours','change_reason') then raise exception 'Protected task field: %',k using errcode='22023'; end if;
 end loop;
 if p_patch ? 'title' and (length(btrim(coalesce(p_patch->>'title',''))) not between 1 and 300) then raise exception 'Enter a task title (up to 300 characters)' using errcode='22023'; end if;
 if p_patch ? 'priority' and coalesce(p_patch->>'priority','') not in ('low','medium','high') then raise exception 'Invalid priority' using errcode='22023'; end if;
 if p_patch ? 'estimated_hours' and (coalesce((p_patch->>'estimated_hours')::numeric,0)<0 or coalesce((p_patch->>'estimated_hours')::numeric,0)>100000) then raise exception 'Effort must be between 0 and 100000 hours' using errcode='22023'; end if;
 if p_patch ? 'budget_impact' and (coalesce((p_patch->>'budget_impact')::numeric,0)<0 or coalesce((p_patch->>'budget_impact')::numeric,0)>1000000000000) then raise exception 'Invalid budget estimate' using errcode='22023'; end if;
 if p_patch ? 'dependency_ids' then
  if jsonb_typeof(p_patch->'dependency_ids')<>'array' or jsonb_array_length(p_patch->'dependency_ids')>100 then raise exception 'Invalid dependency list' using errcode='22023'; end if;
  select coalesce(array_agg(distinct value::uuid),'{}'::uuid[]) into deps from jsonb_array_elements_text(p_patch->'dependency_ids');
  if exists(select 1 from unnest(deps) d where d=t.id or not exists(select 1 from public.tasks x where x.id=d and x.linked_project_id=p.id and x.deleted_at is null)) then raise exception 'Dependencies must be other available tasks in this project' using errcode='22023'; end if;
  with recursive edges(id,path) as (
   select d,array[d] from unnest(deps) d union all
   select d,e.path||d from edges e join public.tasks x on x.id=e.id cross join lateral unnest(x.dependency_ids) d where not d=any(e.path)
  ) select exists(select 1 from edges where id=t.id) into cycle_found;
  if cycle_found then raise exception 'Dependencies cannot form a cycle' using errcode='22023'; end if;
 end if;
 if p_patch ? 'deadline' or p_patch ? 'start_date' then
  v_today := (clock_timestamp() at time zone 'Asia/Manila')::date;
  v_start := case when p_patch ? 'start_date' then nullif(p_patch->>'start_date','')::date else t.start_date end;
  v_due := case when p_patch ? 'deadline' then nullif(p_patch->>'deadline','') else nullif(t.deadline,'') end;
  if p_patch ? 'deadline' and v_due is not null then
   if v_due !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception 'Enter a valid due date.' using errcode='22023';
   end if;
   v_due_day := v_due::date;
   if v_due_day < v_today then raise exception 'Choose today or a future due date.' using errcode='22023'; end if;
   p_patch:=jsonb_set(p_patch,'{deadline}',to_jsonb(v_due));
  end if;
  if v_start is not null and v_start is distinct from t.start_date and v_start < v_today then
   raise exception 'Choose today or a future start date.' using errcode='22023';
  end if;
  if v_start is not null and v_due is not null and v_start > left(v_due,10)::date then
   raise exception 'Due date cannot be before the start date.' using errcode='22023';
  end if;
 end if;
 perform set_config('eflow.work_detail_change_reason',coalesce(p_patch->>'change_reason',''),true);
 update public.tasks set
  title=case when p_patch ? 'title' then btrim(p_patch->>'title') else title end,
  priority=case when p_patch ? 'priority' then p_patch->>'priority' else priority end,
  deadline=case when p_patch ? 'deadline' then coalesce(p_patch->>'deadline','') else deadline end,
  due_date=case when p_patch ? 'deadline' then coalesce(p_patch->>'deadline','') else due_date end,
  start_date=case when p_patch ? 'start_date' then nullif(p_patch->>'start_date','')::date else start_date end,
  estimated_hours=case when p_patch ? 'estimated_hours' then coalesce((p_patch->>'estimated_hours')::double precision,0) else estimated_hours end,
  budget_impact=case when p_patch ? 'budget_impact' then coalesce((p_patch->>'budget_impact')::double precision,0) else budget_impact end,
  dependency_ids=case when p_patch ? 'dependency_ids' then deps else dependency_ids end,
  group_id=case when p_patch ? 'group_id' then (p_patch->>'group_id')::uuid else group_id end,
  workspace_position=case when p_patch ? 'workspace_position' then (p_patch->>'workspace_position')::integer else workspace_position end
 where id=t.id returning * into t;
 perform set_config('eflow.work_detail_change_reason','',true);
 if t.start_date is not null and nullif(t.deadline,'') is not null and t.start_date>left(t.deadline,10)::date then raise exception 'Start date must precede the due date' using errcode='22023'; end if;
 return t;
end; $function$

CREATE OR REPLACE FUNCTION eflow_r7.command(p_root uuid, p_revision integer, p_request uuid, p_command text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb;n eflow_r7.nodes;parent eflow_r7.nodes;v_id uuid:=(p_payload->>'id')::uuid;v_parent uuid:=(p_payload->>'parent')::uuid;v_lead uuid:=(p_payload->>'lead')::uuid;
 v_people uuid[];v_order uuid[];v_subtree uuid[];v_uid uuid;v_receipt eflow_r7.receipts;v_before jsonb;v_result jsonb;v_terms jsonb;v_kind text;v_position int;v_due date;v_previous_status_write text;
begin
 perform eflow_r3.actor();
 if not coalesce(eflow_r7.read_root(p_root),false) then raise exception 'Work access denied' using errcode='42501';end if;
 perform eflow_r7.lock_impact(p_root);
 perform eflow_r3.actor();
 if p_request is null then raise exception 'Request identity required';end if;
 r:=eflow_r7.root(p_root);v_kind:=r->>'kind';
 if not eflow_r7.read_root(p_root) then raise exception 'Work access denied' using errcode='42501';end if;
 perform 1 from public.projects where id=(r->>'project')::uuid for update;
 perform 1 from public.personal_projects where id=(r->>'project')::uuid for update;
 perform eflow_r7.lock_completion(p_root); perform 1 from public.tasks where id=p_root for update;
 perform 1 from public.personal_tasks where id=p_root for update;
 r:=eflow_r7.root(p_root);
 v_terms:=jsonb_build_object('command',p_command,'payload',p_payload);
 select * into v_receipt from eflow_r7.receipts where actor_id=auth.uid() and request_id=p_request;
 if found then
  if v_receipt.root_id<>p_root or v_receipt.payload<>v_terms then raise exception 'Request terms conflict';end if;
  return eflow_r7.snapshot(p_root);
 end if;
 if v_kind='office' and (
  (p_command<>'create' and v_id is not null and not eflow_m7.node_visible(p_root,v_id,auth.uid()))
  or (v_parent is not null and not eflow_m7.node_visible(p_root,v_parent,auth.uid()))
 ) then raise exception 'Current branch access required' using errcode='42501'; end if;
 if v_kind='personal' and p_command in ('progress','submit') and exists (
  select 1 from public.personal_subtasks s where s.id=v_id and s.task_id=p_root
   and s.start_date is not null and s.started_at is null
 ) then raise exception 'This subtask has not started' using errcode='42501'; end if;
 if p_command='contributors' and coalesce(eflow_publication.root_contributor_change_locked(p_root),false) then raise exception 'Only the Task Lead, Project Lead or responsible Office Head can change Task contributors' using errcode='42501';end if;
 if not coalesce((r->>'open')::boolean,false) then raise exception 'Closed or unresolved work is read-only' using errcode='42501';end if;
 if coalesce((select revision from eflow_r7.tree_state where root_id=p_root),1) is distinct from p_revision then raise exception 'Work changed; reload and review the current tree' using errcode='40001';end if;
 if p_payload ? 'dependency_ids' and (v_kind<>'office' or p_command<>'edit'
   or jsonb_typeof(p_payload->'dependency_ids') is distinct from 'array') then
    raise exception 'Choose a list of Office subtask prerequisites.' using errcode='22023';
 end if;
 if p_payload ? 'priority' and (v_kind<>'office' or p_command not in ('create','edit')
      or coalesce(p_payload->>'priority','') not in ('low','medium','high')) then
     raise exception 'Choose Low, Medium or High priority.' using errcode='22023';
 end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k not in ('id','parent','lead','people','title','due','start','priority','dependency_ids','standalone','order','note','progress','approve')) then raise exception 'Unsupported branch fields';end if;
 if v_id is not null then select * into n from eflow_r7.nodes where id=v_id and task_id=p_root;end if;
 if p_command<>'create' and p_command not in ('contributors','order','root_lead') and n.id is null then raise exception 'Choose a node in this root';end if;
 if p_command in ('progress','submit','review') then
  if v_kind<>'personal' then raise exception 'Use the existing Office evidence workflow';end if;
  if not eflow_m7.personal_node_activated(p_root,v_id) then raise exception 'This subtask has not started' using errcode='42501'; end if;
  if not exists(select 1 from eflow_m7.applying_work_proposal a join eflow_m7.work_proposals w on w.id=a.proposal_id
   where a.tx=txid_current() and w.root_id=p_root and w.node_id=v_id and w.reviewer_id=auth.uid()) then
   if p_command='progress' and n.lead_id is distinct from auth.uid() and (r->>'lead')::uuid is distinct from auth.uid()
      or p_command='submit' and (n.lead_id is distinct from auth.uid() or (r->>'lead')::uuid is distinct from auth.uid())
   then raise exception 'Submit this work for the appointed Lead to review' using errcode='42501'; end if;
  end if;
  if p_command='review' then raise exception 'Subitems complete directly; open the work action instead' using errcode='22023';
  elsif not coalesce((eflow_r7.operation_capabilities(p_root,v_id)->(case when p_command='progress' then 'execute' else 'submit' end)->>'allowed')::boolean,false) then raise exception 'Current subitem lead or task lead authority required' using errcode='42501';end if;
 elsif p_command='create' then
  if v_kind='office' and eflow_publication.subtask_planning_locked(p_root) then raise exception 'Only the Task Lead can add or modify subtasks once the project is active' using errcode='42501';end if;
  if not coalesce(eflow_publication.manage_plan(p_root,v_parent),false) then raise exception 'Only a current lead may add work below their branch' using errcode='42501';end if;
 elsif p_command='order' then
  if v_kind='office' and eflow_publication.subtask_planning_locked(p_root) then raise exception 'Only the Task Lead can add or modify subtasks once the project is active' using errcode='42501';end if;
  if not coalesce(eflow_publication.manage_plan(p_root,v_parent),false) then raise exception 'Sibling ordering denied' using errcode='42501';end if;
 elsif p_command='root_lead' then
  if not coalesce(eflow_r7.head(p_root),false) and not (v_kind='office' and eflow_publication.planning_lead((r->>'project')::uuid,(r->>'office')::uuid)) then raise exception 'Current Task Lead appointment authority required' using errcode='42501';end if;
 else
  if p_command in ('edit','move','delete') and v_kind='office' and eflow_publication.subtask_planning_locked(p_root) then
   raise exception 'Only the Task Lead can add or modify subtasks once the project is active' using errcode='42501';
  end if;
  if p_command='staff' and v_kind='office' and eflow_publication.subtask_planning_locked(p_root)
     and (v_lead is distinct from n.lead_id or n.lead_id is distinct from auth.uid()) then
   raise exception 'Subtask assignments are read-only for the Project Lead and Office Head once the project is active' using errcode='42501';
  end if;
  if not coalesce(eflow_publication.manage_plan(p_root,v_id,p_command='staff' and v_lead is distinct from n.lead_id),false) then raise exception 'Branch staffing denied; ancestors and siblings are protected' using errcode='42501';end if;
 end if;
 if p_command='edit' and v_kind='office' then perform eflow_work_edit.check_subtask_edit(p_root,v_id,p_payload);end if;
 if not (p_command='edit' and v_kind='office') and p_command not in ('progress','submit','review','contributors','staff') and n.id is not null and (n.status<>'todo' or n.percent_complete<>0) then raise exception 'Planning changes require untouched work';end if;
 if p_command not in ('progress','submit','review') then perform eflow_r7.require_operation(p_root,p_command,p_payload);end if;
 v_before:=eflow_r7.snapshot(p_root);
 insert into eflow_r7.mutations values(txid_current(),auth.uid(),p_root);
 if p_command='root_lead' then
  if v_kind='office' then
   select coalesce(array_agg(distinct value::uuid),'{}') into v_people from jsonb_array_elements_text(coalesce(p_payload->'people',to_jsonb(array_remove((select team_member_ids from public.tasks where id=p_root)||array[v_lead],null))));
   perform eflow_r7.ensure_office_members((r->>'project')::uuid,(r->>'office')::uuid,array_remove(array[v_lead]||v_people,null));
  end if;
  if v_id is not null or v_lead is null or not eflow_r7.member((r->>'project')::uuid,(r->>'office')::uuid,v_lead) then raise exception 'Choose an eligible selected root lead';end if;
  if v_kind='office' then
   if cardinality(v_people)>200 or not(v_people @> array[v_lead]) then raise exception 'Include the root lead in contributors';end if;
   foreach v_uid in array v_people loop if not eflow_r7.member((r->>'project')::uuid,(r->>'office')::uuid,v_uid) then raise exception 'Choose eligible project people';end if;end loop;
   v_previous_status_write:=current_setting('eflow.allow_status_write',true);
   perform set_config('eflow.allow_status_write','on',true);
   update public.tasks set status=case when status='pending_assignment' then 'todo' else status end,assigned_to=v_lead,assignee_name=(select full_name from public.profiles where id=v_lead),team_member_ids=v_people,team_member_names=array(select full_name from public.profiles where id=any(v_people) order by array_position(v_people,id)) where id=p_root;
   perform set_config('eflow.allow_status_write',coalesce(v_previous_status_write,'off'),true);
  else update public.personal_tasks set lead_id=v_lead,revision=revision+1 where id=p_root;end if;
 elsif p_command='contributors' then
  select coalesce(array_agg(distinct value::uuid),'{}') into v_people from jsonb_array_elements_text(coalesce(p_payload->'people','[]'));
  if cardinality(v_people)>200 or v_kind<>'office' or v_id is not null or not coalesce(eflow_publication.manage_plan(p_root,null),false) then raise exception 'Root contributor operation denied' using errcode='42501';end if;
  if not (v_people @> array[(r->>'lead')::uuid]) then raise exception 'Root lead must remain; transfer uses its responsible Head';end if;
  perform eflow_r7.ensure_office_members((r->>'project')::uuid,(r->>'office')::uuid,v_people);
  foreach v_uid in array v_people loop if not eflow_r7.member((r->>'project')::uuid,(r->>'office')::uuid,v_uid) then raise exception 'Choose selected project people';end if;end loop;
  update public.tasks set team_member_ids=v_people,team_member_names=array(select full_name from public.profiles where id=any(v_people) order by array_position(v_people,id)) where id=p_root;
 elsif p_command='create' then
  if v_parent is not null and exists(select 1 from eflow_r7.nodes where id=v_parent and (status<>'todo' or percent_complete<>0)) then raise exception 'Add children before starting the parent';end if;
  if v_id is null or exists(select 1 from eflow_r7.nodes where id=v_id) or exists(select 1 from public.tasks where id=v_id) or exists(select 1 from public.personal_tasks where id=v_id) then raise exception 'New disjoint node identity required';end if;
  if length(btrim(p_payload->>'title')) not between 1 and 200 then raise exception 'Enter a subitem title';end if;
  select coalesce(max(sibling_order),-1)+1 into v_position from eflow_r7.nodes where task_id=p_root and parent_subtask_id is not distinct from v_parent;
  select coalesce(array_agg(distinct value::uuid),'{}') into v_people from jsonb_array_elements_text(coalesce(p_payload->'people',to_jsonb(array_remove(array[v_lead],null))));
  if v_lead is not null and not(v_people @> array[v_lead]) or cardinality(v_people)>200 then raise exception 'Include the appointed lead in contributors';end if;
  if v_kind='office' then
   perform eflow_r7.ensure_office_members((r->>'project')::uuid,(r->>'office')::uuid,array_remove(array[v_lead]||v_people,null));
   insert into public.subtasks(id,task_id,parent_subtask_id,title,lead_id,assigned_to,assigned_to_ids,sibling_order,position,created_by,due_date,start_date,priority,is_standalone)
   values(v_id,p_root,v_parent,btrim(p_payload->>'title'),v_lead,v_lead,v_people,v_position,(select coalesce(max(position),-1)+1 from public.subtasks where task_id=p_root),auth.uid(),(p_payload->>'due')::date,(p_payload->>'start')::date,coalesce(p_payload->>'priority','medium'),coalesce((p_payload->>'standalone')::boolean,false));
  else
   insert into public.personal_subtasks(id,task_id,parent_subtask_id,title,lead_id,assigned_to_ids,sibling_order,due_date,start_date,is_standalone)
   values(v_id,p_root,v_parent,btrim(p_payload->>'title'),v_lead,v_people,v_position,(p_payload->>'due')::date,(p_payload->>'start')::date,coalesce((p_payload->>'standalone')::boolean,false));
  end if;
 elsif p_command='staff' then
  if n.status='completed' then raise exception 'Completed responsibility is historical';end if;
  select coalesce(array_agg(distinct value::uuid),'{}') into v_people from jsonb_array_elements_text(coalesce(p_payload->'people','[]'));
  if cardinality(v_people)>200 or v_lead is null or not(v_people @> array[v_lead]) then raise exception 'Choose a lead and include them among contributors';end if;
  if v_kind='office' then
   perform eflow_r7.ensure_office_members((r->>'project')::uuid,(r->>'office')::uuid,array_remove(array[v_lead]||v_people,null));
  end if;
  foreach v_uid in array v_people loop if not eflow_r7.member((r->>'project')::uuid,(r->>'office')::uuid,v_uid) then raise exception 'Choose eligible project people';end if;end loop;
  with recursive below as (select id from eflow_r7.nodes where parent_subtask_id=v_id union all select c.id from eflow_r7.nodes c join below b on c.parent_subtask_id=b.id)
   select coalesce(array_agg(id),'{}') into v_subtree from below;
  if exists(select 1 from eflow_r7.nodes c where c.id=any(v_subtree) and c.status<>'completed' and not(c.assigned_to_ids <@ v_people)) then raise exception 'Reassign unfinished descendant workers before removing a branch contributor';end if;
  if v_kind='office' then
   update public.subtasks set lead_id=v_lead,assigned_to=v_lead,assigned_to_ids=v_people where id=v_id;
   if n.lead_id is distinct from v_lead then update public.subtasks set lead_id=null where id=any(v_subtree);end if;
  else
   update public.personal_subtasks set lead_id=v_lead,assigned_to_ids=v_people where id=v_id;
   if n.lead_id is distinct from v_lead then update public.personal_subtasks set lead_id=null where id=any(v_subtree);end if;
  end if;
 elsif p_command in ('edit','move','delete') then
  with recursive below as (select * from eflow_r7.nodes where id=v_id union all select c.* from eflow_r7.nodes c join below b on c.parent_subtask_id=b.id)
   select array_agg(id) into v_subtree from below;
  if not (p_command='edit' and v_kind='office') and exists(select 1 from eflow_r7.nodes c where c.id=any(v_subtree) and (c.status<>'todo' or c.percent_complete<>0)) then raise exception 'The entire subtree must be untouched';end if;
  if p_command='move' then
   if not coalesce(eflow_publication.manage_plan(p_root,v_parent),false) or v_parent=any(v_subtree) then raise exception 'Destination branch denied or cycle';end if;
   select * into parent from eflow_r7.nodes where id=v_parent and task_id=p_root;
   if v_parent is not null and parent.id is null then raise exception 'Destination must share the root';end if;
   select coalesce(max(sibling_order),-1)+1 into v_position from eflow_r7.nodes where task_id=p_root and parent_subtask_id is not distinct from v_parent;
   if v_kind='office' then update public.subtasks set parent_subtask_id=v_parent,sibling_order=v_position where id=v_id;else update public.personal_subtasks set parent_subtask_id=v_parent,sibling_order=v_position where id=v_id;end if;
   if v_kind='office' then update public.subtasks set parent_subtask_id=parent_subtask_id,lead_id=null where id=any(v_subtree) and id<>v_id;else update public.personal_subtasks set parent_subtask_id=parent_subtask_id,lead_id=null where id=any(v_subtree) and id<>v_id;end if;
  elsif p_command='edit' then
   v_due:=(p_payload->>'due')::date;
   if v_due is not null and exists(select 1 from eflow_r7.nodes c where c.id=any(v_subtree) and c.id<>v_id and c.due_date>v_due) then raise exception 'Edit descendant dates before shortening this deadline';end if;
   if length(btrim(p_payload->>'title')) not between 1 and 200 then raise exception 'Enter a title';end if;
   perform set_config('eflow.subtask_deadline_authorized','on',true);
   if v_kind='office' then if (v_due is distinct from n.due_date or
      (p_payload ? 'start' and (p_payload->>'start')::date is distinct from
        (select s.start_date from public.subtasks s where s.id=v_id)))
      and nullif(btrim(p_payload->>'note'),'') is null then
      raise exception 'Enter a reason for the schedule change.' using errcode='22023';
    end if;
    update public.subtasks set dependency_ids=case when p_payload ? 'dependency_ids'
    then array(select value::uuid from jsonb_array_elements_text(p_payload->'dependency_ids')) else dependency_ids end,
    title=btrim(p_payload->>'title'),priority=coalesce(p_payload->>'priority',priority),due_date=v_due,start_date=case when p_payload ? 'start' then (p_payload->>'start')::date else start_date end,due_date_change_reason=case when v_due is distinct from due_date or (p_payload ? 'start' and (p_payload->>'start')::date is distinct from start_date) then btrim(p_payload->>'note') else due_date_change_reason end,
      due_date_changed_at=case when v_due is distinct from due_date or (p_payload ? 'start' and (p_payload->>'start')::date is distinct from start_date) then now() else due_date_changed_at end,
      due_date_changed_by=case when v_due is distinct from due_date or (p_payload ? 'start' and (p_payload->>'start')::date is distinct from start_date) then auth.uid() else due_date_changed_by end,is_standalone=coalesce((p_payload->>'standalone')::boolean,is_standalone) where id=v_id;
   else update public.personal_subtasks set title=btrim(p_payload->>'title'),due_date=v_due,start_date=case when p_payload ? 'start' then (p_payload->>'start')::date else start_date end,is_standalone=coalesce((p_payload->>'standalone')::boolean,is_standalone) where id=v_id;end if;
   perform set_config('eflow.subtask_deadline_authorized','off',true);
  else
   if v_kind='office' and (exists(select 1 from public.subtask_progress_updates where subtask_id=any(v_subtree)) or exists(select 1 from public.subtask_submissions where subtask_id=any(v_subtree))
    or exists(select 1 from public.work_budget_allocations where subtask_id=any(v_subtree)) or exists(select 1 from public.petty_cash_requests where subtask_id=any(v_subtree))
    or exists(select 1 from public.budget_ledger_entries where subtask_id=any(v_subtree))) then raise exception 'Evidence, budget and cash history prohibit subtree deletion';end if;
   loop
    select id into v_uid from eflow_r7.nodes c where c.id=any(v_subtree) and not exists(select 1 from eflow_r7.nodes d where d.parent_subtask_id=c.id) limit 1;
    exit when v_uid is null;
    if v_kind='office' then delete from public.subtasks where id=v_uid;else delete from public.personal_subtasks where id=v_uid;end if;
   end loop;
  end if;
 elsif p_command='order' then
  select coalesce(array_agg(value::uuid),'{}') into v_order from jsonb_array_elements_text(coalesce(p_payload->'order','[]'));
  if (select count(*) from eflow_r7.nodes where task_id=p_root and parent_subtask_id is not distinct from v_parent)<>cardinality(v_order)
   or (select count(distinct u) from unnest(v_order) u)<>cardinality(v_order) or exists(select 1 from unnest(v_order) u where not exists(select 1 from eflow_r7.nodes c where c.id=u and c.task_id=p_root and c.parent_subtask_id is not distinct from v_parent and c.status='todo' and c.percent_complete=0)) then raise exception 'Order must contain every untouched sibling exactly once';end if;
  if v_kind='office' then update public.subtasks set sibling_order=array_position(v_order,id)-1 where id=any(v_order);else update public.personal_subtasks set sibling_order=array_position(v_order,id)-1 where id=any(v_order);end if;
 elsif p_command in ('progress','submit','review') then
  if p_command<>'review' and not n.is_standalone and exists(select 1 from eflow_r7.nodes c where c.task_id=p_root and c.parent_subtask_id is not distinct from n.parent_subtask_id and c.sibling_order<n.sibling_order and not c.is_standalone and c.status<>'completed') then raise exception 'Complete earlier ordered siblings first';end if;
  if p_command in ('submit','review') and exists(with recursive below as (select * from eflow_r7.nodes where parent_subtask_id=v_id union all select c.* from eflow_r7.nodes c join below b on c.parent_subtask_id=b.id) select 1 from below where status<>'completed') then raise exception 'Complete every child step first';end if;
  if p_command='progress' then
   if (p_payload->>'progress')::int not between 0 and 99 then raise exception 'Progress must be 0–99; submit at completion';end if;
   update public.personal_subtasks set percent_complete=(p_payload->>'progress')::int,status='in_progress',note=coalesce(p_payload->>'note','') where id=v_id;
  elsif p_command='submit' then
   update public.personal_subtasks set status='completed',percent_complete=100,note=coalesce(p_payload->>'note',''),submitted_by=auth.uid(),reviewer_id=null where id=v_id;
  else
   raise exception 'Subitems complete directly; review the parent task instead' using errcode='22023';
  end if;
 else raise exception 'Unsupported work command';end if;
 if v_kind='office' and p_command not in ('contributors','progress','submit','review') then
  if exists(select 1 from pg_constraint where conrelid='public.subtasks'::regclass and conname='subtasks_task_position_unique') then set constraints public.subtasks_task_position_unique deferred;end if;
  with recursive ordered as (
   select id,array[lpad(sibling_order::text,10,'0')||id::text] path from public.subtasks where task_id=p_root and parent_subtask_id is null
   union all select c.id,p.path||(lpad(c.sibling_order::text,10,'0')||c.id::text) from public.subtasks c join ordered p on c.parent_subtask_id=p.id where c.task_id=p_root
  ), ranked as (select id,row_number() over(order by path)-1 rank from ordered)
  update public.subtasks s set position=r.rank from ranked r where s.id=r.id and s.position<>r.rank;
  if exists(select 1 from pg_constraint where conrelid='public.subtasks'::regclass and conname='subtasks_task_position_unique') then set constraints public.subtasks_task_position_unique immediate;end if;
 end if;
 delete from eflow_r7.mutations where tx=txid_current() and actor=auth.uid() and root_id=p_root;
 v_result:=eflow_r7.snapshot(p_root);
 insert into public.work_tree_events(root_id,project_id,actor_id,actor_name,command,node_id,before_data,after_data) values(p_root,(r->>'project')::uuid,auth.uid(),(select full_name from public.profiles where id=auth.uid()),p_command,v_id,v_before,v_result);
 if v_kind='office' and p_command in ('create','staff','contributors','root_lead') then
  foreach v_uid in array coalesce(v_people,'{}') loop
   if v_uid<>auth.uid() and not coalesce((case when p_command in ('contributors','root_lead') then v_before->'root'->'people' else (select to_jsonb(assigned_to_ids) from jsonb_to_recordset(v_before->'nodes') as old_node(id uuid,assigned_to_ids uuid[]) where id=v_id) end) ? v_uid::text,false) then
    insert into public.notifications(user_id,type,title,message,task_id,task_title,actor_id,actor_name,project_id,work_node_id)
    values(v_uid,'assignment',case when v_id is null then 'Task assignment' else 'Subtask assignment' end,'You were assigned to "'||coalesce(p_payload->>'title',n.title,(select title from public.tasks where id=p_root))||'".',p_root,(select title from public.tasks where id=p_root),auth.uid(),(select full_name from public.profiles where id=auth.uid()),(r->>'project')::uuid,v_id);
   end if;
  end loop;
 end if;
 insert into eflow_r7.receipts values(auth.uid(),p_request,p_root,v_terms,v_result);
 return v_result;
end $function$
